  // copies the texture it can see along with the shape it was asked for, which
  // would hand a type 1 user someone else's curls. Said outright, the reference
  // is demoted to what it is actually good for here: the geometry of the cut.
  const shotAs = variant && variant !== 'any' ? variant : null;
  if (!shotAs || shotAs === type) return line;

  return (
    `${line} The reference is modelled on ${HAIR_TYPE_LABELS[shotAs]} hair, which is not this ` +
    "person's: take the cut's shape, length and outline from it, not its texture."
  );
