  const keep =
    "**Keep the person's original hair colour.** The hair in the finished image must be the same " +
    'colour it is in the photograph — the haircut changes, the shade does not.';
  return hasReference
    ? `${keep} The reference's hair colour is not part of the haircut and must not be copied.`
    : keep;
